export function getFunnelPageBySlug(slug: string): FunnelPageData | undefined {
    return FUNNEL_PAGES.find((p) => p.slug === slug);
}

export function getFunnelPageByCode(code: string): FunnelPageData | undefined {
    return FUNNEL_PAGES.find((p) => p.code === code);
}
